orderWatch.query:
query LuxeStyleNewPaidOrderEvidence {
 shop { id name url currencyCode primaryDomain { host url } }
 orders(first: 5, sortKey: CREATED_AT, reverse: false, query: "created_at:>='2026-10-28T23:48:36Z' created_at:<='2026-10-29T07:09:37Z'") {
  nodes { id name createdAt test cancelledAt displayFinancialStatus
   currentTotalPriceSet { shopMoney { amount currencyCode } }
   totalRefundedSet { shopMoney { amount currencyCode } }
   transactions { id kind status test manualPaymentGateway gateway processedAt amountSet { shopMoney { amount currencyCode } } }
  }
  pageInfo { hasNextPage endCursor }
 }
}
